// ─── CONFIGURAZIONE ───────────────────────────────────
// Cambia il percorso della cartella dove salvare le immagini:
const OUTPUT_FOLDER = 'C:/Users/arzig/OneDrive/Desktop/unrealkiara/img/generated';

// Modello Replicate (flux-schnell = veloce/economico | flux-dev = più qualità)
const MODEL = 'black-forest-labs/flux-schnell';
// ──────────────────────────────────────────────────────

const BASE = 'young Italian woman, minimalist fashion, warm tones ivory peach champagne sand, soft natural light, photorealistic, editorial fashion photography, Italian aesthetic, intimate mood, square format 1:1';

const prompts = [
  // ── RITUAL (mattina, domestico) ──
  { pillar:'ritual', slug:'morning-window',    prompt: `${BASE}, in ivory linen pajama set, holding white ceramic coffee cup, standing by large window, sheer curtains, warm morning light filtering, Italian apartment interior, soft grain` },
  { pillar:'ritual', slug:'coffee-hands',      prompt: `${BASE}, close-up of hands wrapped around ceramic mug, steaming coffee, wooden table, ivory linen cloth, morning light, warm peach tones, detail shot` },
  { pillar:'ritual', slug:'white-sheets',      prompt: `${BASE}, lying in white cotton sheets, peach morning light, bare shoulder, relaxed reading, Italian apartment, warm minimal interior` },
  { pillar:'ritual', slug:'barefoot-floor',    prompt: `${BASE}, barefoot on warm wooden floor, ivory interior, soft morning sun rays, minimal decor, lifestyle photography` },
  { pillar:'ritual', slug:'mirror-gaze',       prompt: `${BASE}, facing mirror in minimal ivory bathroom, soft warm steam, calm expression, morning ritual, no make-up natural skin` },

  // ── WORLD (luoghi, momenti) ──
  { pillar:'world',  slug:'cobblestone-walk',  prompt: `${BASE}, walking on cobblestone street, wide-leg linen trousers sand color, tucked ivory blouse, warm afternoon, Milan Italy, blurred ochre background, candid editorial` },
  { pillar:'world',  slug:'cafe-outdoor',      prompt: `${BASE}, sitting at marble outdoor cafe table, peach midi dress, cappuccino, dappled sunlight, Italian summer, candid lifestyle` },
  { pillar:'world',  slug:'ochre-wall',        prompt: `${BASE}, leaning against warm ochre wall, golden hour light, simple cream linen outfit, shadow play, Italian city street` },
  { pillar:'world',  slug:'olive-trees',       prompt: `${BASE}, standing among olive trees, ivory and sage green linen dress, Mediterranean afternoon light, dreamy soft focus background` },
  { pillar:'world',  slug:'train-window',      prompt: `${BASE}, looking out of train window, soft motion blur outside, warm interior light, champagne outfit, contemplative expression` },
  { pillar:'world',  slug:'flower-market',     prompt: `${BASE}, at outdoor flower market, ivory outfit, touching fresh peach flowers, warm natural light, candid lifestyle, Italian market` },
  { pillar:'world',  slug:'rooftop-sunset',    prompt: `${BASE}, on rooftop terrace at golden hour, flowing champagne dress, Italian city skyline soft focus, warm sunset light` },

  // ── ARMADIO (outfit, moda) ──
  { pillar:'outfit', slug:'linen-sand-set',    prompt: `${BASE}, full length, wide-leg sand linen trousers, tucked ivory fitted top, minimal gold jewelry, clean warm studio, even soft light, editorial fashion` },
  { pillar:'outfit', slug:'slip-dress-champ',  prompt: `${BASE}, champagne slip dress midi length, spaghetti straps, natural window light, minimal white interior, soft shadows, editorial` },
  { pillar:'outfit', slug:'cacao-blazer',      prompt: `${BASE}, oversized cacao brown blazer, ivory blouse underneath, against warm beige stone wall, editorial fashion` },
  { pillar:'outfit', slug:'all-cream-layers',  prompt: `${BASE}, layered all-cream outfit, linen and cotton textures, movement, warm diffused studio light, clean background` },
  { pillar:'outfit', slug:'peach-trousers',    prompt: `${BASE}, peach fitted top, wide albicocca orange high-waist trousers, outdoor movement shot, hair flowing, warm afternoon light` },
  { pillar:'outfit', slug:'ivory-coat-winter', prompt: `${BASE}, long ivory wool coat, winter editorial, stone architecture background, elegant minimal, cold clear day` },
  { pillar:'outfit', slug:'white-linen-dress', prompt: `${BASE}, simple white linen dress, sun-drenched outdoor, relaxed natural pose, warm afternoon, lifestyle editorial` },
  { pillar:'outfit', slug:'rust-knit-autumn',  prompt: `${BASE}, rust terracotta knit sweater, Italian countryside, golden autumn light, relaxed fashion editorial` },

  // ── MUSE / EDITORIALE ──
  { pillar:'muse',   slug:'studio-editorial',  prompt: `${BASE}, minimalist studio, ivory background, avant-garde relaxed pose, fashion editorial, Vogue Italia aesthetic, high fashion` },
  { pillar:'muse',   slug:'beauty-portrait',   prompt: `${BASE}, close-up portrait, bare skin, minimal makeup, warm side light, editorial beauty, natural Italian aesthetic, intimate` },
  { pillar:'muse',   slug:'fabric-shadow',     prompt: `${BASE}, artistic fashion shot, strong shadow play on ivory fabric, graphic composition, editorial mood, minimal` },

  // ── SFONDI / TEXTURE (per Voce e Drop) ──
  { pillar:'texture',slug:'flatlay-ivory',     prompt: `flat lay, ivory linen fabric, champagne silk, small pearl earring, ceramic object, warm morning light, editorial product photography, overhead, no person, square format` },
  { pillar:'texture',slug:'warm-abstract',     prompt: `abstract warm background, ivory peach cream tones, soft shadows, no people, minimal texture, perfect text overlay background, editorial aesthetic, square format` }
];

return prompts.map((p, i) => ({ json: {
  index:         i + 1,
  total:         prompts.length,
  pillar:        p.pillar,
  slug:          p.slug,
  prompt:        p.prompt,
  filename:      `kiara-${p.pillar}-${p.slug}.webp`,
  outputFolder:  OUTPUT_FOLDER,
  model:         MODEL
}}));

const res     = $input.first().json;
const meta    = $('Loop').first().json;

if(res.status !== 'succeeded' || !res.output || !res.output[0]){
  throw new Error(`Replicate error [${meta.slug}]: status=${res.status} | ${res.error || 'no output'}`);
}

return [{ json: {
  ...meta,
  imageUrl: res.output[0],
  predictionId: res.id
}}];

// Tutte le 25 immagini generate con successo
const total = $('Prompt List (25)').all().length;
return [{ json: {
  status: 'done',
  message: `✅ ${total} immagini Kiara generate e salvate.`,
  folder: $('Prompt List (25)').first().json.outputFolder
}}];
